StartPage.onData(function (data) {
  var stat = data.integration && data.integration.stats && data.integration.stats[0];
  document.getElementById("value").textContent = stat ? stat.value + (stat.unit ? " " + stat.unit : "") : "-";
  document.getElementById("label").textContent = stat ? stat.label : "Pick an integration in the widget settings";
});

StartPage.onData(function (data) {
  var list = document.getElementById("list");
  list.textContent = "";
  data.services.forEach(function (s) {
    var li = document.createElement("li");
    li.className = s.status;
    li.textContent = s.name + (s.latency_ms != null ? " - " + s.latency_ms + " ms" : "");
    list.appendChild(li);
  });
});

function tick() {
  var now = new Date();
  document.getElementById("time").textContent = now.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", second: "2-digit" });
  document.getElementById("date").textContent = now.toLocaleDateString([], { weekday: "long", month: "long", day: "numeric" });
}
tick();
setInterval(tick, 1000);
